C552_R = [('<button class="sb rst" data-rst="1">초기화 (모든 기록 삭제)</button>`,', '<button class="sb rst" data-rst="1">초기화 (모든 기록 삭제)</button><div style="height:8px"></div><button class="sb rst" data-rst="2">튜토리얼 클리어 상태로 초기화</button>`,   /* c552 */'), ("            if (!b.classList.contains('on')) { b.classList.add('on'); b.textContent = '정말 초기화? 한 번 더 누르기'; setTimeout(() => { if (b.isConnected) { b.classList.remove('on'); b.textContent = '초기화 (모든 기록 삭제)'; } }, 3000); return; }\n            try { localStorage.removeItem('rd_genes'); localStorage.setItem('rd_save_v1', JSON.stringify({ genes: 0, clr: {}, sub: {}, up: { hp: 0, ahp: 0, atk: 0 }, tut: false, mig: 1, v2: 1, v3: 1, v4: 1 })); window.name = ''; } catch (e) {}", "            const t2 = b.dataset.rst === '2', lab = t2 ? '튜토리얼 클리어 상태로 초기화' : '초기화 (모든 기록 삭제)';   /* c552: 튜토리얼만 깬 상태 — 보상 500 + 시민 30명 몫 30 */\n            if (!b.classList.contains('on')) { b.classList.add('on'); b.textContent = '정말 초기화? 한 번 더 누르기'; setTimeout(() => { if (b.isConnected) { b.classList.remove('on'); b.textContent = lab; } }, 3000); return; }\n            try { localStorage.removeItem('rd_genes'); localStorage.setItem('rd_save_v1', JSON.stringify({ genes: t2 ? 530 : 0, clr: {}, sub: {}, up: { hp: 0, ahp: 0, atk: 0 }, tut: t2, mig: 1, v2: 1, v3: 1, v4: 1 })); window.name = ''; } catch (e) {}")]
